// U2: Convert .mpga to .mp3（模板 Code 节点逐字移植）
function convert(items){
  // ===== 模板原文开始 =====
  return items.map(item => {
    const b = item.binary?.audio;
    if (!b) return item;
    item.binary.audio_mp3 = {
      ...b,
      fileName: (b.fileName || 'audio.mp3').replace(/\.mpga$/i, '.mp3'),
      mimeType: 'audio/mpeg'
    };
    return item;
  });
  // ===== 模板原文结束 =====
}
let out = convert([{json:{}, binary:{audio:{data:'B64', fileName:'voice.mpga', mimeType:'audio/x-mpga'}}}]);
let nb = out[0].binary.audio_mp3;
T('U2 mpga改名mp3', nb.fileName==='voice.mp3');
T('U2 mime改audio/mpeg', nb.mimeType==='audio/mpeg');
T('U2 data保留', nb.data==='B64');
T('U2 原binary.audio保留(模板注释掉了delete)', !!out[0].binary.audio);
out = convert([{json:{x:1}}]);
T('U2 无binary原样透传', !out[0].binary && out[0].json.x===1);
